function cleanText(value, max = 2000) {
  return Array.from(String(value ?? '').normalize('NFC').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '').trim()).slice(0, max).join('');
}

function canonicalProfile(value) {
  const s = cleanText(value, 2000);
  const m = /^https:\/\/(?:[a-z0-9-]+\.)?linkedin\.com\/in\/([^/?#\s]+)(?:[/?#][^\s]*)?$/i.exec(s);
  return m ? 'https://www.linkedin.com/in/' + m[1].toLowerCase() : '';
}

function validPeopleSearch(value) {
  return /^https:\/\/(?:www\.)?linkedin\.com\/(?:search\/results\/people\/?|sales\/search\/people\/?)(?:\?[^#\s]*)?$/i.test(String(value));
}

function fingerprint(value) {
  let h = 2166136261;
  for (const c of String(value)) { h ^= c.codePointAt(0); h = Math.imul(h, 16777619); }
  return (h >>> 0).toString(16).padStart(8, '0');
}

function exactObject(value, keys) {
  return value !== null && typeof value === 'object' && !Array.isArray(value)
    && Object.keys(value).length === keys.length && keys.every(k => Object.prototype.hasOwnProperty.call(value, k));
}

function toolPayload(response, name) {
  if (!response || response.error || response.type === 'error' || response.stop_reason !== 'tool_use' || !Array.isArray(response.content)) {
    return { error: 'Model response failed, was truncated, or did not return the required structured result.' };
  }
  const blocks = response.content.filter(b => b.type === 'tool_use');
  if (blocks.length !== 1 || blocks[0].name !== name) return { error: 'Expected exactly one named structured result.' };
  return { value: blocks[0].input };
}

function validateScoreResponse(response) {
  const parsed = toolPayload(response, 'score_lead');
  if (parsed.error) return parsed;
  const v = parsed.value;
  if (!exactObject(v, ['score', 'reason']) || !Number.isInteger(v.score) || v.score < 1 || v.score > 10
      || typeof v.reason !== 'string' || !cleanText(v.reason) || v.reason.length > 2000) {
    return { error: 'Score must be an integer from 1 to 10 with a non-empty reason and no extra fields.' };
  }
  return { value: { score: v.score, reason: cleanText(v.reason) } };
}

function validateDraftResponse(response) {
  const parsed = toolPayload(response, 'draft_outreach');
  if (parsed.error) return parsed;
  const v = parsed.value;
  if (!exactObject(v, ['connection_note', 'm1_message']) || typeof v.connection_note !== 'string'
      || typeof v.m1_message !== 'string' || !cleanText(v.connection_note) || !cleanText(v.m1_message)
      || Array.from(v.connection_note.trim()).length > 200 || v.m1_message.length > 1500) {
    return { error: 'Both outreach drafts must be non-empty; connection note is limited to 200 characters. Invalid drafts remain Pending.' };
  }
  return { value: { connection_note: cleanText(v.connection_note, 1000), m1_message: cleanText(v.m1_message, 1500) } };
}

function normalizedProfiles(items) {
  if (!Array.isArray(items)) throw new Error('Completed search output.items must be an array.');
  const seen = new Set();
  const out = [];
  let duplicates = 0;
  for (const raw of items) {
    const p = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
    const url = canonicalProfile(p.public_profile_url);
    const key = url || 'invalid-' + fingerprint(JSON.stringify(raw));
    if (seen.has(key)) { duplicates++; continue; }
    seen.add(key);
    const role = Array.isArray(p.current_positions) ? p.current_positions[0] || {} : {};
    out.push({
      profile_key: key,
      public_profile_url: url,
      first_name: cleanText(p.first_name, 200), last_name: cleanText(p.last_name, 200),
      headline: cleanText(p.headline, 1000), position1_role: cleanText(role.role, 500),
      position1_company: cleanText(role.company, 500), location: cleanText(p.location, 500),
      industry: cleanText(Array.isArray(role.industry) ? role.industry.join(', ') : role.industry, 500),
      summary: cleanText(p.summary, 3000),
      review_error: url ? '' : 'Search result has no valid HTTPS LinkedIn person URL; review the source record manually.',
    });
  }
  return { profiles: out, rawCount: items.length, duplicates };
}

function summarizeReceipts(items) {
  if (!Array.isArray(items) || items.length === 0) throw new Error('No durable profile receipts were returned.');
  const first = items[0];
  const ids = new Set(), counts = { Qualified: 0, Rejected: 0, Pending: 0 };
  for (const r of items) {
    if (r.notion_page_id !== first.notion_page_id || r.result_id !== first.result_id || r.expected_count !== first.expected_count) {
      throw new Error('Mixed search batches detected. Refusing to update Notion.');
    }
    if (r.persisted !== true || !r.row_key || ids.has(r.row_key) || !Object.prototype.hasOwnProperty.call(counts, r.review_status)) {
      throw new Error('Missing, duplicate, or invalid persistence receipt. Refusing to update Notion.');
    }
    ids.add(r.row_key); counts[r.review_status]++;
  }
  if (ids.size !== first.expected_count) throw new Error('Not every expected profile has a unique durable receipt.');
  return { ...first, durable_count: ids.size, qualified_count: counts.Qualified, rejected_count: counts.Rejected,
    pending_count: counts.Pending, completion_eligible: counts.Pending === 0,
    search_error: counts.Pending ? 'One or more profiles need manual review. Notion remains Pending.' : '' };
}

function assertReadback(actualRows, expected) {
  if (!Array.isArray(actualRows) || actualRows.length !== 1) throw new Error('Expected exactly one persisted row. Missing or duplicate rows require review.');
  const actual = actualRows[0];
  for (const [key, value] of Object.entries(expected)) {
    if (String(actual[key] ?? '') !== String(value ?? '')) throw new Error('Readback mismatch for column: ' + key);
  }
  return true;
}

function assertNotionCompletion(actual, expectedPage, expectedTimestamp) {
  const compact = value => String(value || '').replaceAll('-', '').toLowerCase();
  const timestamp = actual?.properties?.['Processed At']?.date?.start;
  if (compact(actual?.id) !== compact(expectedPage) || actual?.properties?.Status?.select?.name !== 'Done'
      || !Number.isFinite(Date.parse(expectedTimestamp)) || Date.parse(timestamp || '') !== Date.parse(expectedTimestamp)) {
    throw new Error('Notion update did not acknowledge the exact completed page, status and timestamp.');
  }
  return true;
}

const cfg = { ...$json };
for (const key of ['notionDatabaseId', 'googleSheetId', 'periodixProfileId', 'productContext', 'icpCriteria', 'anthropicModel', 'leadTab', 'auditTab']) {
  if (typeof cfg[key] !== 'string' || !cfg[key].trim() || /^CONFIGURE_/i.test(cfg[key])) throw new Error('Complete Central Configuration: ' + key);
  cfg[key] = cfg[key].trim();
}
