function validateScoreResponse(response) {
  const parsed = toolPayload(response, 'score_lead');
  if (parsed.error) return parsed;
  const v = parsed.value;
  if (!exactObject(v, ['score', 'reason']) || !Number.isInteger(v.score) || v.score < 1 || v.score > 10
      || typeof v.reason !== 'string' || !cleanText(v.reason) || v.reason.length > 2000) {
    return { error: 'Score must be an integer from 1 to 10 with a non-empty reason and no extra fields.' };
